function drawTower(p){let t=towerTypes[p.tower];ctx.save();ctx.translate(p.x,p.y-7);ctx.fillStyle='#514a38';ctx.beginPath();ctx.ellipse(0,8,15,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=t.color;ctx.beginPath();ctx.arc(0,-2,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff2c2';ctx.beginPath();ctx.arc(0,-3,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#5e4d32';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(0,-19);ctx.stroke();ctx.restore();}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawEnemies(){for(const e of enemies){if(e.dead)continue;const p=positionOnPath(e.distance);ctx.save();ctx.translate(p.x,p.y+Math.sin(e.bob)*3);ctx.fillStyle=e.color;ctx.beginPath();ctx.ellipse(0,0,e.size,e.size*.78,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6e8ca';ctx.beginPath();ctx.arc(-4,-2,2,0,Math.PI*2);ctx.arc(4,-2,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle=e.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-7,-e.size*.6);ctx.lineTo(-11,-e.size);ctx.moveTo(7,-e.size*.6);ctx.lineTo(11,-e.size);ctx.stroke();ctx.fillStyle='#27332b';ctx.fillRect(-e.size,e.size+3,e.size*2,3);ctx.fillStyle='#e77562';ctx.fillRect(-e.size,e.size+3,e.size*2*(e.hp/e.maxHp),3);ctx.restore();}}
function positionOnPath(d){let n=d;for(let i=1;i<path.length;i++){let a=path[i-1],b=path[i],len=Math.hypot(b.x-a.x,b.y-a.y);if(n<=len){return{x:a.x+(b.x-a.x)*n/len,y:a.y+(b.y-a.y)*n/len}}n-=len}return path[path.length-1]}
function drawShots(){for(const s of shots){ctx.strokeStyle=s.color;ctx.lineWidth=3;ctx.globalAlpha=.85;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.tx,s.ty);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#fff4b7';ctx.beginPath();ctx.arc(s.tx,s.ty,3,0,Math.PI*2);ctx.fill()}}
function drawParticles(){for(const p of particles){ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1}
function drawOverlay(){if(phase==='day'){ctx.fillStyle='#15231caa';roundRect(16,16,145,26,6);ctx.fill();ctx.fillStyle='#e7e9d1';ctx.font='10px DM Mono';ctx.textAlign='left';ctx.fillText('GARDEN PLOT  ·  12 BEDS',27,33)}else{ctx.fillStyle='#16241edb';roundRect(16,16,210,47,7);ctx.fill();ctx.fillStyle='#d9e3ce';ctx.font='10px DM Mono';ctx.textAlign='left';ctx.fillText(phase==='night'?'THREATS ON THE OLD ROAD':'A QUIET MOMENT',28,34);ctx.fillStyle='#899a88';ctx.font='9px DM Mono';ctx.fillText(phase==='night'?`WAVE ${Math.floor((day+1)/2)}  ·  ${enemies.length} REMAINING`:'TOWERS HOLD THE LINE',28,50)}}
function plantOrHarvest(p){if(!p.crop){let c=cropTypes[tool];if(gold<c.cost){notify('Not enough gold for those seeds.');return}gold-=c.cost;p.crop={type:tool,progress:0,grow:c.grow,ready:false};notify(`${c.name} seeds planted!`)}else if(p.crop.ready){let c=cropTypes[p.crop.type];gold+=c.reward;harvest++;p.crop=null;notify(`Harvest sold for ${c.reward} gold!`)}else notify('Still growing — give it a little time.');updateUI()}
function buildTower(p){if(p.tower){selectedPad=p;notify(`${towerTypes[p.tower].name} is already guarding this spot.`);return}let t=towerTypes[tool];if(!t){tool='lantern';t=towerTypes[tool];updateUI()}if(gold<t.cost){notify('Not enough gold to build that.');return}gold-=t.cost;p.tower=tool;notify(`${t.name} is ready to defend!`);updateUI()}
function pointer(e){const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*W/rect.width,y=(e.clientY-rect.top)*H/rect.height;if(phase==='day'){let p=plots.find(p=>x>=p.x&&x<=p.x+p.w&&y>=p.y&&y<=p.y+p.h);if(p)plantOrHarvest(p)}else{let p=pads.find(p=>Math.hypot(p.x-x,p.y-y)<27);if(p){if(phase==='night'&&p.tower){notify('Your tower is already covering the road.');return}buildTower(p)}}}
function startNight(){phase='night';nightTime=0;waveSpawned=0;kills=0;enemies.length=0;shots.length=0;for(const p of plots)if(p.crop&&p.crop.progress>=p.crop.grow)p.crop.ready=true;notify('The forest stirs. Keep your homestead safe!');updateUI()}
function startDay(){phase='day';day++;hp=Math.min(100,hp+12);gold+=5;enemies.length=0;shots.length=0;for(const p of plots){if(p.crop){p.crop.progress+=1;if(p.crop.progress>=p.crop.grow)p.crop.ready=true}}tool='turnip';notify(`Dawn breaks. +5g and 12% homestead repairs.`);updateUI()}
function advance(){if(phase==='day')startNight();else if(phase==='dawn')startDay()}
function spawnEnemy(){let wave=Math.floor((day+1)/2),isBoss=wave%3===0&&waveSpawned===Math.ceil((3+wave)*1.25)-1;let e={distance:0,hp:isBoss?110+wave*8:32+wave*8,maxHp:isBoss?110+wave*8:32+wave*8,speed:isBoss?29:38+Math.min(wave*2,14),size:isBoss?13:9,color:isBoss?'#b75f68':['#a76962','#7c7893','#ba8758'][Math.floor(Math.random()*3)],bob:rand(0,6),boss:isBoss};enemies.push(e);waveSpawned++}
function update(dt){if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').classList.remove('show')}if(phase==='day'){for(const p of plots)if(p.crop&&!p.crop.ready){p.crop.progress+=dt/18;if(p.crop.progress>=p.crop.grow)p.crop.ready=true}}
if(phase==='night'){nightTime+=dt;let total=Math.ceil((3+Math.floor((day+1)/2))*1.25);if(waveSpawned<total&&nightTime>waveSpawned*(2.3-Math.min(day*.08,.8)))spawnEnemy();for(const e of enemies){if(e.dead)continue;e.distance+=e.speed*dt;e.bob+=dt*5;if(e.distance>=pathLength()){e.dead=true;hp=Math.max(0,hp-(e.boss?25:12));notify('A creature reached your homestead!');updateUI()}}
for(const p of pads){if(!p.tower)continue;let t=towerTypes[p.tower];p.cool=(p.cool||0)-dt;if(p.cool<=0){let target=enemies.filter(e=>!e.dead&&Math.hypot(positionOnPath(e.distance).x-p.x,positionOnPath(e.distance).y-p.y)<t.range).sort((a,b)=>b.distance-a.distance)[0];if(target){let pos=positionOnPath(target.distance);shots.push({x:p.x,y:p.y-8,tx:pos.x,ty:pos.y,color:t.color,life:.13});target.hp-=t.damage;target.flash=.1;p.cool=t.rate;if(target.hp<=0){target.dead=true;gold+=target.boss?12:2;kills++;for(let n=0;n<6;n++)particles.push({x:pos.x,y:pos.y,life:1,color:t.color,vx:rand(-20,20),vy:rand(-25,10)});updateUI()}}}}
for(let i=shots.length-1;i>=0;i--){shots[i].life-=dt;if(shots[i].life<=0)shots.splice(i,1)}for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=(p.vx||0)*dt;p.y+=(p.vy||0)*dt;if(p.life<=0)particles.splice(i,1)}enemies.splice(0,enemies.length,...enemies.filter(e=>!e.dead));if(hp<=0){gameOver=true;document.getElementById('lostNight').textContent=day;document.getElementById('defeat').classList.add('on')}else if(waveSpawned>=total&&enemies.length===0){phase='dawn';gold+=8;notify(`Wave cleared! ${kills} threats stopped · +8g`);updateUI()}}
}
function pathLength(){let d=0;for(let i=1;i<path.length;i++)d+=Math.hypot(path[i].x-path[i-1].x,path[i].y-path[i-1].y);return d}
function frame(now){let dt=Math.min(.05,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(frame)}
canvas.addEventListener('pointerdown',pointer);document.getElementById('phaseBtn').onclick=advance;document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();advance()}if(e.key==='Escape')document.getElementById('help').classList.remove('open')});
function showHelp(){document.getElementById('help').classList.add('open')}document.getElementById('helpBtn').onclick=showHelp;document.getElementById('helpBtnMobile').onclick=showHelp;document.getElementById('closeHelp').onclick=()=>document.getElementById('help').classList.remove('open');
document.getElementById('restart').onclick=()=>{day=1;phase='day';gold=24;harvest=0;hp=100;gameOver=false;plots.forEach(p=>p.crop=null);pads.forEach(p=>{p.tower=null;p.cool=0});enemies.length=0;document.getElementById('defeat').classList.remove('on');tool='turnip';updateUI();notify('A fresh start in Moonroot Valley.')};
updateUI();requestAnimationFrame(frame);
})();
</script></body></html>

